call: load_skill({"skill_name": "fees"})
result: {
 "skill_name": "fees",
 "instructions": "# Explaining fees\n\n1. Call `get_fee_schedule` to get the current fee bands. Do not quote fees from\n   memory; they change.\n2. Find the band for the amount the customer asked about and give the fee in\n   KES, with the band (for example \"KES 13 for 1,501 to 2,500\").\n3. If the customer was charged a fee they think is wrong, find the transaction\n   first, then compare the fee charged with the band.\n4. Keep the answer to two sentences.",
 "frontmatter": {
  "name": "fees",
  "description": "Use when a customer asks what a transfer costs, or why they were charged a fee.",
  "license": null,
  "compatibility": null,
  "allowed_tools": null,
  "metadata": {
   "adk_additional_tools": [
    "get_fee_schedule"
   ]
  }
 }
}

