call: load_skill({"skill_name": "statements"})
result: {
 "skill_name": "statements",
 "instructions": "# Sending a statement\n\n1. Work out which month the customer wants. If they did not say, ask.\n2. Check how the customer wants to receive it. Look for any pinned constraint\n   or profile preference about channels (SMS, email, app inbox) and respect it.\n   Only fall back to the channel on file when nothing else applies.\n3. Call `send_statement` with the month and, when known, the channel.\n4. Confirm where the statement went. Never read out the full statement in the\n   chat; it can contain other people's numbers.",
 "frontmatter": {
  "name": "statements",
  "description": "Use when a customer asks for an account statement, a transaction history document, or proof of payments for a month.",
  "license": null,
  "compatibility": null,
  "allowed_tools": null,
  "metadata": {
   "adk_additional_tools": [
    "send_statement"
   ]
  }
 }
}

